void build_lps(const char *p, int m, int lps[]) {
  int len = 0; lps[0] = 0;
  for (int i = 1; i < m; ) {
    if (p[i] == p[len]) lps[i++] = ++len;
    else if (len) len = lps[len - 1];     // fall back, do not advance i
    else lps[i++] = 0;
  }
}

int kmp(const char *t, const char *p) {
  int n = strlen(t), m = strlen(p), i = 0, j = 0, pos = -1;
  int *lps = malloc(m * sizeof *lps);
  build_lps(p, m, lps);
  while (i < n) {
    if (t[i] == p[j]) { i++; j++; if (j == m) { pos = i - j; break; } }
    else if (j) j = lps[j - 1];
    else i++;
  }
  free(lps); return pos;
}
